<template>
  <LabToolPage :meta="meta">
    <section class="lab-workspace qr-workspace" aria-labelledby="qr-workspace-title">
      <div class="lab-panel qr-controls-panel">
        <div class="lab-panel-heading"><div><p class="card-kicker">01 · ENCODE</p><h2 id="qr-workspace-title">把一段内容折成二维码</h2></div><span class="lab-step">本地</span></div>
        <div class="lab-tab-list" role="tablist" aria-label="二维码类型"><button v-for="item in types" :key="item.id" class="lab-tab" :class="{ active: qrType === item.id }" type="button" role="tab" :aria-selected="qrType === item.id" @click="qrType = item.id">{{ item.label }}</button></div>
        <div v-if="qrType === 'text' || qrType === 'url'" class="lab-setting-group qr-fields"><label for="qr-content">{{ qrType === 'url' ? '网址' : '文本' }}</label><textarea id="qr-content" v-model="content" class="lab-textarea" rows="5" maxlength="4000" :placeholder="qrType === 'url' ? 'https://example.com' : '写下要编码的内容'"></textarea></div>
        <div v-else-if="qrType === 'wifi'" class="lab-setting-group qr-fields"><label>Wi-Fi 名称<input v-model="wifi.ssid" class="lab-input" maxlength="120"></label><label>密码<input v-model="wifi.password" class="lab-input" maxlength="120" type="text"></label><label>加密<select v-model="wifi.encryption" class="lab-select"><option value="WPA">WPA / WPA2</option><option value="WEP">WEP</option><option value="nopass">无密码</option></select></label><label class="lab-check"><input v-model="wifi.hidden" type="checkbox"><span>隐藏网络</span></label></div>
        <div v-else class="lab-setting-group qr-fields"><label>{{ qrType === 'email' ? '邮箱地址' : '电话号码' }}<input v-model="contact.value" class="lab-input" :type="qrType === 'email' ? 'email' : 'tel'" maxlength="160"></label><label v-if="qrType === 'email'">主题<input v-model="contact.subject" class="lab-input" maxlength="120"></label><label v-if="qrType === 'email'">正文<textarea v-model="contact.body" class="lab-textarea" rows="3" maxlength="1000"></textarea></label></div>
        <div class="lab-setting-group"><div class="lab-number-grid"><label><span>尺寸</span><select v-model.number="size" class="lab-select"><option :value="256">256 px</option><option :value="512">512 px</option><option :value="1024">1024 px</option></select></label><label><span>容错</span><select v-model="errorCorrection" class="lab-select"><option value="L">L · 低</option><option value="M">M · 默认</option><option value="Q">Q · 高</option><option value="H">H · 最高</option></select></label></div><div class="lab-number-grid"><label class="lab-color-input"><span>前景色</span><input v-model="darkColor" type="color"></label><label class="lab-color-input"><span>背景色</span><input v-model="lightColor" type="color"></label></div><label><span>留白 {{ margin }}</span><input v-model.number="margin" class="lab-range" type="range" min="0" max="8"></label></div>
        <button class="lab-button is-primary lab-full-button" type="button" :disabled="state === 'loading'" @click="generate">{{ state === 'loading' ? '生成中…' : '生成二维码' }}</button><p v-if="errorMessage" class="lab-message is-error" role="alert">{{ errorMessage }}</p><p class="lab-privacy-line">二维码在当前浏览器中生成。URL 只负责编码，不代表 Levi Blog 对目标网址做安全背书。</p>
      </div>
      <div class="lab-panel qr-result-panel" aria-live="polite"><div class="lab-panel-heading"><div><p class="card-kicker">02 · PREVIEW</p><h2>带走这张二维码</h2></div><span v-if="qrDataUrl" class="lab-status is-success">已生成</span></div><div v-if="!qrDataUrl" class="lab-empty-result"><span class="lab-empty-result-icon is-qr" role="img" aria-label="二维码图标"></span><h3>还没有二维码</h3><p>输入文本或联系方式后，结果会留在当前浏览器里。</p></div><template v-else><div class="qr-preview"><img :src="qrDataUrl" alt="生成的二维码"></div><div class="qr-encoded"><small>实际编码内容</small><code>{{ payload }}</code></div><div class="lab-result-actions"><button class="lab-button is-primary" type="button" @click="downloadPng">下载 PNG</button><button class="lab-button is-secondary" type="button" @click="downloadSvg">下载 SVG</button><button class="lab-button is-secondary" type="button" @click="copyPayload">{{ copied ? '已复制内容' : '复制原始内容' }}</button></div></template></div>
    </section>
  </LabToolPage>
</template>

<script setup lang="ts">
import { labTools } from '~/data/lab-tools'
const meta = labTools.find((tool) => tool.id === 'qr')!
const types = [{ id: 'text', label: '文本' }, { id: 'url', label: 'URL' }, { id: 'wifi', label: 'Wi-Fi' }, { id: 'email', label: '邮箱' }, { id: 'phone', label: '电话' }] as const
type QrType = typeof types[number]['id']; const qrType = ref<QrType>('text'); const content = ref(''); const wifi = reactive({ ssid: '', password: '', encryption: 'WPA', hidden: false }); const contact = reactive({ value: '', subject: '', body: '' }); const size = ref(512); const margin = ref(2); const errorCorrection = ref<'L' | 'M' | 'Q' | 'H'>('M'); const darkColor = ref('#2F3B32'); const lightColor = ref('#FFFDF5'); const qrDataUrl = ref(''); const qrSvg = ref(''); const state = ref<'idle' | 'loading'>('idle'); const errorMessage = ref(''); const copied = ref(false)
const payload = computed(() => { if (qrType.value === 'text' || qrType.value === 'url') return content.value.trim(); if (qrType.value === 'wifi') return `WIFI:T:${wifi.encryption};S:${escapeWifi(wifi.ssid)};P:${escapeWifi(wifi.password)};H:${wifi.hidden ? 'true' : 'false'};;`; if (qrType.value === 'phone') return `tel:${contact.value.trim()}`; const params = new URLSearchParams(); if (contact.value.trim()) params.set('subject', contact.subject); if (contact.body) params.set('body', contact.body); return `mailto:${contact.value.trim()}${params.toString() ? '?' + params.toString() : ''}` })
function escapeWifi(value: string) { return value.replace(/([\\;,:"])/g, '\\$1') }
async function generate() { const value = payload.value; if (!value || (qrType.value === 'url' && !/^https?:\/\//i.test(value))) { errorMessage.value = qrType.value === 'url' ? '请输入以 http:// 或 https:// 开头的网址。' : '请先输入要编码的内容。'; return }; state.value = 'loading'; errorMessage.value = ''; try { const { toDataURL, toString } = await import('qrcode'); const options = { errorCorrectionLevel: errorCorrection.value, margin: margin.value, width: size.value, color: { dark: darkColor.value, light: lightColor.value } }; qrDataUrl.value = await toDataURL(value, options); qrSvg.value = await toString(value, { ...options, type: 'svg' }) } catch { errorMessage.value = '二维码生成失败，请缩短内容后重试。' } finally { state.value = 'idle' } }
function downloadPng() { if (!qrDataUrl.value) return; const link = document.createElement('a'); link.href = qrDataUrl.value; link.download = 'levi-lab-qr.png'; link.click() }
function downloadSvg() { if (!qrSvg.value) return; const blob = new Blob([qrSvg.value], { type: 'image/svg+xml' }); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = 'levi-lab-qr.svg'; link.click(); URL.revokeObjectURL(url) }
async function copyPayload() { try { await navigator.clipboard.writeText(payload.value); copied.value = true; window.setTimeout(() => copied.value = false, 1500) } catch { errorMessage.value = '无法复制，请手动选择原始内容。' } }
watch([qrType, content, wifi, contact, size, margin, errorCorrection, darkColor, lightColor], () => { qrDataUrl.value = ''; qrSvg.value = '' }, { deep: true })
useBlogSeo({ title: '二维码工作台', description: '在浏览器本地生成文本、URL、Wi-Fi、邮箱和电话二维码，支持 PNG、SVG、容错等级与颜色设置。', canonical: '/lab/qr', keywords: '二维码生成,URL二维码,Wi-Fi二维码', breadcrumbs: [{ name: '手账实验室', path: '/lab' }, { name: '二维码工作台', path: '/lab/qr' }] })
</script>
